impl Add<&Ciphertext> for &Ciphertext {
    type Output = Ciphertext;

    fn add(self, rhs: &Ciphertext) -> Ciphertext {
        assert!(Arc::ptr_eq(&self.par, &rhs.par));

        if self.is_empty() {
            return rhs.clone();
        }
        if rhs.is_empty() {
            return self.clone();
        }

        assert_eq!(self.level, rhs.level);
        assert_eq!(self.len(), rhs.len());

        let c = self
            .iter()
            .zip(rhs.iter())
            .map(|(c1i, c2i)| c1i + c2i)
            .collect::<Vec<_>>();
        Ciphertext {
            par: self.par.clone(),
            seed: None,
            c,
            level: self.level,
        }
    }
}

impl Add<&Ciphertext> for Ciphertext {
    type Output = Ciphertext;

    fn add(mut self, rhs: &Ciphertext) -> Ciphertext {
        self += rhs;
        self
    }
}

impl AddAssign<&Ciphertext> for Ciphertext {
    fn add_assign(&mut self, rhs: &Ciphertext) {
        assert!(Arc::ptr_eq(&self.par, &rhs.par));

        if self.is_empty() {
            *self = rhs.clone()
        } else if !rhs.is_empty() {
            assert_eq!(self.level, rhs.level);
            assert_eq!(self.len(), rhs.len());
            self.iter_mut()
                .zip(rhs.iter())
                .for_each(|(c1i, c2i)| *c1i += c2i);
            self.seed = None
        }
    }

impl Sub<&Ciphertext> for &Ciphertext {
    type Output = Ciphertext;

    fn sub(self, rhs: &Ciphertext) -> Ciphertext {
        assert!(Arc::ptr_eq(&self.par, &rhs.par));

        if self.is_empty() {
            return -rhs.clone();
        }
        if rhs.is_empty() {
            return self.clone();
        }

        assert_eq!(self.level, rhs.level);
        assert_eq!(self.len(), rhs.len());

        let c = self
            .iter()
            .zip(rhs.iter())
            .map(|(c1i, c2i)| c1i - c2i)
            .collect::<Vec<_>>();
        Ciphertext {
            par: self.par.clone(),
            seed: None,
            c,
            level: self.level,
        }
    }
}

