    fn mul_assign(&mut self, rhs: &Plaintext) {
        assert!(Arc::ptr_eq(&self.par, &rhs.par));
        if !self.is_empty() {
            assert_eq!(self.level, rhs.level);
            self.iter_mut().for_each(|ci| *ci *= &rhs.poly_ntt);
        }
        self.seed = None
